    if (isLast && loop) return; // a loop: the start's marker is the end's too
    const pin = !isFirst && !isLast && isPinned(p);
    const el = ptEl(isFirst ? 'start' : isLast ? 'end' : pin ? 'pin' : 'mid', pin ? String(++pinNo) : isFirst && loop ? '↺' : '');
    el.title = isFirst ? (loop ? 'Start and end' : 'Start') : isLast ? 'Destination' : pin ? tx('Stop {n}', { n: pinNo }) : 'Shaping point';
    const m = new maplibregl.Marker({ element: el, draggable: true }).setLngLat([p[0], p[1]]).addTo(map); // a point carries pin + label: MapLibre takes [lng, lat] only
