  const vals = state.mode === 'omni' && state.show === 'norm' ? res.norm : res.cur;
  const q = quantileRank(vals);
  // very large corridors: draw only the RENDER_MAX roads carrying the most current (memory / GPU on phones)
  const RENDER_MAX = 50000;
  let n = 0; for (let e = 0; e < vals.length; e++) if (vals[e] > 0) n++;
  const minQ = n > RENDER_MAX ? 1 - RENDER_MAX / n : -1;
