// Flyover: a low chase camera that follows a route over MapLibre's 3D terrain, like a bird flying behind the rider.
// Nothing is decided frame by frame: when a flight starts, the route is resampled every STEP metres, Gaussian-smoothed
// and turned into cubic Bézier curves (Catmull-Rom through the smoothed points), once for where the camera looks
// (sigma `look`) and once, much smoother, for the compass heading (sigma `turn`). Each frame only evaluates those curves
// at the rider's distance t, so the camera glides through switchbacks and corners instead of twitching at every vertex.
// The camera's height is a smoothed profile too: the look-at point rides the smoothed route elevation, lifted where the
// ground behind (under the camera) rises, and MapLibre is told that height directly (it otherwise re-reads the terrain
// under the map centre every frame, which bobs as DEM tiles load and change zoom).
// Pitch and zoom are the viewer's: the first flight uses a default low chase (back / height / ahead below); tilt or
// zoom the map while paused and the next ▶ keeps that, only turning the compass to the direction of travel.
//
// track: routeTrack(coords, zAt) — positions are metres along the route polyline (t in [0, L]).
// createFlyover(map, { onMove(t, lngLat), onChange({ active, playing, speed }), terrain: { source, exaggeration } or a function returning it })
//   .start(track, t0)  saves the view, turns 3D terrain on, starts playing from t0
//   .play() .pause() .toggle()  .setPos(t) (pauses; used when scrubbing the elevation profile)
//   .cycleSpeed()  .exit() restores the view and the terrain setting
export const FLY = { back: 520, ahead: 160, height: 190, look: 120, turn: 320, step: 25, speeds: [500, 1000, 2000], ease: 0.6 };

const R2D = 180 / Math.PI;
// planar helpers around a latitude (metres)
const kxAt = (lat) => Math.cos(lat / R2D) * 111320, KY = 110574;
export function offset([lon, lat], bearingDeg, dist) {
  const b = bearingDeg / R2D;
  return [lon + (Math.sin(b) * dist) / kxAt(lat), lat + (Math.cos(b) * dist) / KY];
}
const bearingOf = (dx, dy, lat) => Math.atan2(dx * kxAt(lat), dy * KY) * R2D;

// coords: [[lon, lat], ...]; zAt(t): route elevation in metres at distance t (optional)
export function routeTrack(coords, zAt = () => 0) {
  const cs = coords, cum = [0];
  for (let k = 1; k < cs.length; k++) { const kx = kxAt(cs[k][1]); cum.push(cum[k - 1] + Math.hypot((cs[k][0] - cs[k - 1][0]) * kx, (cs[k][1] - cs[k - 1][1]) * KY)); }
  const L = cum[cum.length - 1];
  const at = (t) => {
    const d = Math.max(0, Math.min(L, t));
    let lo = 1, hi = cum.length - 1; // first index with cum >= d
    while (lo < hi) { const m = (lo + hi) >> 1; if (cum[m] < d) lo = m + 1; else hi = m; }
    const j = lo, f = cum[j] > cum[j - 1] ? (d - cum[j - 1]) / (cum[j] - cum[j - 1]) : 0;
    return [cs[j - 1][0] + f * (cs[j][0] - cs[j - 1][0]), cs[j - 1][1] + f * (cs[j][1] - cs[j - 1][1])];
  };
  return { coords: cs, cum, L, at, zAt };
}

// Gaussian smoothing of evenly spaced samples; beyond the ends the series is mirrored through the end value (odd:
// keeps the end direction, for positions) or held (even: for heights)
export function gauss(v, sigmaSamples, odd = true) {
  const n = v.length, r = Math.ceil(sigmaSamples * 3); if (!(sigmaSamples > 0) || n < 2) return v.slice();
  const w = []; let ws = 0; for (let k = -r; k <= r; k++) { const x = Math.exp(-(k * k) / (2 * sigmaSamples * sigmaSamples)); w.push(x); ws += x; }
  const get = (i) => (i < 0 ? (odd ? 2 * v[0] - v[Math.min(n - 1, -i)] : v[0]) : i >= n ? (odd ? 2 * v[n - 1] - v[Math.max(0, 2 * (n - 1) - i)] : v[n - 1]) : v[i]);
  const out = new Float64Array(n);
  for (let i = 0; i < n; i++) { let s = 0; for (let k = -r; k <= r; k++) s += w[k + r] * get(i + k); out[i] = s / ws; }
  return out;
}

// A smooth curve through the route: samples every `step` m along it, Gaussian-smoothed with `sigma` m, joined by cubic
// Bézier segments (Catmull-Rom tangents). Parameterised by route distance, so curve(t) stays level with the rider.
// .pos(t) -> [lon, lat]   .bearing(t) -> compass degrees of the curve's tangent (continuous: the curve is C1)
export function smoothCurve(track, sigma, step = FLY.step) {
  const n = Math.max(2, Math.ceil(track.L / step) + 1), ds = track.L / (n - 1);
  const raw = Array.from({ length: n }, (_, i) => track.at(i * ds));
  const sx = gauss(raw.map((p) => p[0]), sigma / ds), sy = gauss(raw.map((p) => p[1]), sigma / ds);
  const P = (i, a) => { const v = a ? sy : sx; return i < 0 ? 2 * v[0] - v[Math.min(n - 1, -i)] : i >= n ? 2 * v[n - 1] - v[Math.max(0, 2 * (n - 1) - i)] : v[i]; };
  // segment i: P_i -> P_i+1 with Bézier handles B1 = P_i + (P_i+1 - P_i-1)/6, B2 = P_i+1 - (P_i+2 - P_i)/6
  const seg = (t) => { const u = Math.max(0, Math.min(n - 1, t / ds)), i = Math.min(n - 2, Math.floor(u)); return [i, u - i]; };
  const ctrl = (i, a) => { const p0 = P(i, a), p3 = P(i + 1, a); return [p0, p0 + (p3 - P(i - 1, a)) / 6, p3 - (P(i + 2, a) - p0) / 6, p3]; };
  const bez = ([a, b, c, d], f) => { const g = 1 - f; return g * g * g * a + 3 * g * g * f * b + 3 * g * f * f * c + f * f * f * d; };
  const dbez = ([a, b, c, d], f) => { const g = 1 - f; return 3 * (g * g * (b - a) + 2 * g * f * (c - b) + f * f * (d - c)); };
  const pos = (t) => { const [i, f] = seg(t); return [bez(ctrl(i, 0), f), bez(ctrl(i, 1), f)]; };
  const bearing = (t) => { const [i, f] = seg(t), y = bez(ctrl(i, 1), f); return bearingOf(dbez(ctrl(i, 0), f), dbez(ctrl(i, 1), f), y); };
  return { pos, bearing, ds, n };
}

const wrap180 = (a) => ((((a + 180) % 360) + 360) % 360) - 180;
const smoothstep = (x) => x * x * (3 - 2 * x);

// The viewer's pitch / zoom (kept for the page's lifetime: a new flight starts the way the last one was left)
let view = null;

export function createFlyover(map, { onMove = () => {}, onChange = () => {}, terrain = null } = {}) {
  let track = null, t = 0, playing = false, speedIdx = 0, raf = 0, last = 0, saved = null, addedTerrain = false;
  let look = null, turn = null, elev = null, elevKey = '', userMoved = false, blend = null;
  const exag = () => map.getTerrain()?.exaggeration ?? 1;
  const state = () => ({ active: !!track, playing, speed: speedIdx, t, L: track?.L ?? 0 });
  // metres from the camera to the map centre at this zoom / latitude (MapLibre: 512 px tiles)
  const camDist = (zoom, lat) => map.transform.cameraToCenterDistance * (40075016.686 * Math.cos(lat / R2D)) / (512 * 2 ** zoom);
  // the default chase: `back` behind the rider and `height` above, looking `ahead` of the rider
  function defaultView() {
    const rider = track.at(t), b = turn.bearing(t), cam = offset(rider, b + 180, FLY.back), target = offset(rider, b, FLY.ahead);
    const o = map.calculateCameraOptionsFromTo(new maplibregl.LngLat(cam[0], cam[1]), FLY.height, new maplibregl.LngLat(target[0], target[1]), 0);
    return { pitch: o.pitch, zoom: o.zoom };
  }
  // height of the look-at point along the route (sampled like the curves): the smoothed route elevation, lifted where
  // the ground under the camera (about `hd` metres back along the route) would come within 60 m of it
  function heights() {
    const key = `${view.pitch.toFixed(1)}|${view.zoom.toFixed(2)}|${exag()}`; if (elev && key === elevKey) return;
    const n = look.n, ds = look.ds, ex = exag(), lat = track.at(track.L / 2)[1];
    const d3 = camDist(view.zoom, lat), dz = d3 * Math.cos(view.pitch / R2D), hd = d3 * Math.sin(view.pitch / R2D);
    const z = Array.from({ length: n }, (_, i) => (track.zAt(i * ds) || 0) * ex);
    const base = gauss(z, FLY.look / ds, false), w = Math.max(1, Math.round(120 / ds)), back = Math.round((hd - FLY.ahead) / ds);
    const lifted = base.map((e, i) => { let g = -Infinity; for (let k = i - back - w; k <= i - back + w; k++) g = Math.max(g, z[Math.max(0, Math.min(n - 1, k))]); return Math.max(e, g + 60 - dz); });
    elev = gauss(gauss(lifted, FLY.look / ds, false), FLY.look / ds, false); elevKey = key;
  }
  const elevAt = (tt) => { const u = Math.max(0, Math.min(look.n - 1, tt / look.ds)), i = Math.min(look.n - 2, Math.floor(u)), f = u - i; return elev[i] * (1 - f) + elev[i + 1] * f; };
  function place(dt) {
    heights();
    const ta = Math.min(track.L, t + FLY.ahead), c = look.pos(ta);
    let center = c, bearing = turn.bearing(t), e = elevAt(ta);
    if (blend) { // resuming after the viewer moved the map: glide from their view onto the curve
      blend.k = Math.min(1, blend.k + (dt ?? 0) / FLY.ease); const k = smoothstep(blend.k);
      center = [blend.center[0] + (c[0] - blend.center[0]) * k, blend.center[1] + (c[1] - blend.center[1]) * k];
      bearing = blend.bearing + wrap180(bearing - blend.bearing) * k; e = blend.elev + (e - blend.elev) * k;
      if (blend.k >= 1) blend = null;
    }
    // MapLibre re-reads the terrain under the centre each frame unless frozen; hand it the smoothed height instead
    map._elevationFreeze = true; map.transform.elevation = e;
    map.jumpTo({ center, bearing, pitch: view.pitch, zoom: view.zoom });
    onMove(t, track.at(t));
  }
  function frame(now) {
    raf = 0;
    if (!track || !playing) return;
    const dt = last ? Math.min(0.5, (now - last) / 1000) : 0; last = now; // slow devices keep real speed (choppier), up to 2 fps
    t = Math.min(track.L, t + FLY.speeds[speedIdx] * dt);
    place(dt);
    if (t >= track.L) { pause(); return; }
    raf = requestAnimationFrame(frame);
  }
  function play() {
    if (!track) return;
    if (t >= track.L) t = 0;
    if (userMoved) { // keep the viewer's tilt and zoom; the heading and position come back to the route
      view = { pitch: map.getPitch(), zoom: map.getZoom() };
      const c = map.getCenter(); blend = { k: 0, center: [c.lng, c.lat], bearing: map.getBearing(), elev: map.transform.elevation };
      userMoved = false;
    }
    playing = true; last = 0;
    if (!raf) raf = requestAnimationFrame(frame);
    onChange(state());
  }
  function pause() { playing = false; if (raf) cancelAnimationFrame(raf); raf = 0; onChange(state()); }
  function start(tr, t0 = 0) {
    if (!tr || tr.L < 50) return;
    if (!track) {
      saved = { center: map.getCenter(), zoom: map.getZoom(), bearing: map.getBearing(), pitch: map.getPitch() };
      const tz = typeof terrain === 'function' ? terrain() : terrain;
      if (!map.getTerrain() && tz && map.getSource(tz.source)) { map.setTerrain(tz); addedTerrain = true; }
    }
    if (tr !== track) { look = smoothCurve(tr, FLY.look); turn = smoothCurve(tr, FLY.turn); elev = null; }
    track = tr; t = Math.max(0, Math.min(tr.L, t0)); userMoved = false; blend = null;
    view ??= defaultView();
    place(null);
    play();
  }
  function setPos(nt) {
    if (!track) return; if (playing) pause();
    if (userMoved) { view = { pitch: map.getPitch(), zoom: map.getZoom() }; userMoved = false; }
    blend = null; t = Math.max(0, Math.min(track.L, nt)); place(null); onChange(state());
  }
  function exit() {
    if (!track) return;
    pause(); track = null; look = turn = elev = null; blend = null; userMoved = false;
    map._elevationFreeze = false;
    if (addedTerrain) { map.setTerrain(null); addedTerrain = false; }
    if (saved) map.easeTo({ ...saved, duration: 600 });
    saved = null;
    onChange(state());
  }
  // a user drag / zoom / rotate / tilt pauses the flight (programmatic jumpTo events carry no originalEvent), and the
  // next play keeps the tilt and zoom they chose
  map.on('movestart', (e) => { if (!track || !e.originalEvent) return; userMoved = true; blend = null; if (playing) pause(); });
  // HTML markers are placed with the terrain height known at the time; once tiles finish loading, place the rider again
  map.on('idle', () => { if (track && !playing) onMove(t, track.at(t)); });
  return { start, play, pause, toggle: () => (playing ? pause() : play()), setPos, exit,
    cycleSpeed: () => { speedIdx = (speedIdx + 1) % FLY.speeds.length; onChange(state()); return speedIdx; },
    get active() { return !!track; }, get playing() { return playing; }, get t() { return t; }, get track() { return track; }, state };
}
