// Which tiles a live build fetches, per source, for a buffered route or a rectangle. Shared by the builder
// (build-core.mjs) and the app (download estimate before a big build), so it imports nothing heavy.
//   source 'gsi' (Japan): GSI experimental_bvmap z14 roads + dem_png z13 elevation; for traffic, VersaTiles OSM z13
//                         (class votes, bike paths) and a ring of GSI z11 major roads
//   source 'osm' (world): VersaTiles OSM z14 roads (Shortbread `streets`) + AWS Terrain Tiles z13 elevation (Terrarium
//                         PNG, 256 px: 19 m pixels at the equator, 12-16 m at 35-52 degrees); for traffic, a ring of
//                         VersaTiles z11 tiles (trunk/primary/secondary are complete there)
import { corridor, routeTiles, projectorAt } from '../route.mjs';

export const ROAD_Z = 14, DEM_Z = 13, OSM_Z = 13, RING_Z = 11, RING_M = 10000;
export const roadUrl = (t) => `https://cyberjapandata.gsi.go.jp/xyz/experimental_bvmap/${t.z}/${t.x}/${t.y}.pbf`;
export const demUrl = (t) => `https://cyberjapandata.gsi.go.jp/xyz/dem_png/${t.z}/${t.x}/${t.y}.png`;
export const vtUrl = (t) => `https://tiles.versatiles.org/tiles/osm/${t.z}/${t.x}/${t.y}`;
export const terrariumUrl = (t) => `https://s3.amazonaws.com/elevation-tiles-prod/terrarium/${t.z}/${t.x}/${t.y}.png`;

// tile kinds per source: [kind, zoom, url, ring?, traffic only?, average MB per tile on the wire]
// GSI sizes are the app's measured averages. VersaTiles tiles carry every layer (buildings, addresses), so their
// size follows how built-up the place is: z14 measured 0.16-0.32 MB (mean 0.22) in central Amsterdam but ~3 kB in
// rural Iwate, z13 there ~15 kB, z11 around Amsterdam 0.13 MB. The OSM figures are for a city, so the estimate
// is on the high side elsewhere.
const KINDS = {
  gsi: [['road', ROAD_Z, roadUrl, false, false, 0.027], ['dem', DEM_Z, demUrl, false, false, 0.11],
    ['osm', OSM_Z, vtUrl, false, true, 0.05], ['ring', RING_Z, roadUrl, true, true, 0.03]],
  osm: [['road', ROAD_Z, vtUrl, false, false, 0.2], ['dem', DEM_Z, terrariumUrl, false, false, 0.1],
    ['ring', RING_Z, vtUrl, true, true, 0.13]],
};

// Slippy-map tiles at zoom z that intersect the box [west, south, east, north], grown by padM metres
export function boxTiles([w, s, e, n], z, padM = 0) {
  const dLat = padM / 110574, dLon = padM / (111320 * Math.cos((((s + n) / 2) * Math.PI) / 180)), N = 2 ** z;
  const tx = (lon) => Math.max(0, Math.min(N - 1, Math.floor(((lon + 180) / 360) * N)));
  const ty = (lat) => { const r = (Math.max(-85, Math.min(85, lat)) * Math.PI) / 180; return Math.floor(((1 - Math.log(Math.tan(r) + 1 / Math.cos(r)) / Math.PI) / 2) * N); };
  const out = [];
  for (let x = tx(w - dLon); x <= tx(e + dLon); x++) for (let y = ty(n + dLat); y <= ty(s - dLat); y++) out.push({ z, x, y });
  return out;
}

// A rectangle in the shape route.mjs corridor() returns, so the builder treats both alike: projection around the
// box centre, dist = metres outside the box (0 inside), no route parts.
export function areaCorridor([w, s, e, n]) {
  const proj = projectorAt((w + e) / 2, (s + n) / 2), [x0, y0] = proj([w, s]), [x1, y1] = proj([e, n]);
  return { parts: [], proj, bufM: 0, bbox: [w, s, e, n], bboxLocal: [x0, y0, x1, y1],
    dist: (x, y) => Math.hypot(Math.max(x0 - x, 0, x - x1), Math.max(y0 - y, 0, y - y1)) };
}

// Every tile a build fetches, in fetch order: [{ kind: 'road'|'dem'|'osm'|'ring', t: { z, x, y }, url, mb }].
// area = [west, south, east, north] replaces the buffered route.
export function liveTiles(route, bufM, { source = 'gsi', area = null, traffic = true } = {}) {
  if (!KINDS[source]) throw new Error(`unknown live source ${source}`);
  const C = area ? null : corridor(route, bufM), jobs = [];
  for (const [kind, z, url, ring, trafficOnly, mb] of KINDS[source]) {
    if (trafficOnly && !traffic) continue;
    const tiles = area ? boxTiles(area, z, ring ? RING_M : 0) : ring ? routeTiles(C.parts, bufM + RING_M, z) : routeTiles(C, bufM, z);
    for (const t of tiles) jobs.push({ kind, t, url: url(t), mb });
  }
  return jobs;
}

// Download size of a build before anything is cached: { tiles, mb } (mb from the per-kind averages above)
export function tileEstimate(route, bufM, opts = {}) {
  const jobs = liveTiles(route, bufM, opts);
  return { tiles: jobs.length, mb: +jobs.reduce((s, j) => s + j.mb, 0).toFixed(1) };
}

// Which side of the road traffic keeps to at [lon, lat]: 'left' | 'right'. A small table of boxes [w, s, e, n],
// first match wins, default right. It is approximate near land borders (e.g. Thailand/Laos, India/Myanmar,
// Zambia/Congo), which a few right-hand boxes ahead of the left-hand ones only partly correct, and it leaves out
// small islands (Bahamas, Barbados, Mauritius, Fiji ...).
const DRIVE_SIDE = [
  ['left', 130.8, 30, 146.5, 41.5], ['left', 139, 41.5, 146.5, 45.6], ['left', 128, 32, 130.8, 34.75], ['left', 122.5, 24, 132, 30.5], // Japan
  ['left', -10.7, 49.85, 0.3, 61], ['left', 0.3, 50.8, 1.45, 61], ['left', 1.45, 51, 1.8, 61], ['left', -2.7, 49.1, -2, 49.75], // Britain, Ireland, Channel Islands
  ['left', 32.2, 34.5, 34.6, 35.75], ['left', 14.1, 35.75, 14.6, 36.1],                 // Cyprus, Malta
  ['left', 112, -44.5, 154.5, -9.5], ['left', 165.5, -47.5, 179, -34],                  // Australia, New Zealand
  ['left', 113.82, 22.15, 114.45, 22.54], ['left', 113.52, 22.1, 113.6, 22.22],         // Hong Kong, Macau
  ['right', 117, 7.5, 127, 21], ['right', 119.5, 4.5, 127, 7.5],                        // Philippines
  ['right', 105.7, 8.5, 111.3, 23.5], ['right', 102.95, 9.9, 105.7, 14.3],              // Vietnam, Hainan, Cambodia
  ['right', 101.2, 18.45, 105.7, 23.5], ['right', 102.45, 17.9, 103.2, 18.45],          // northern Laos, Vientiane
  ['right', 94.5, 15.8, 97.9, 25.9],                                                    // Myanmar (roughly)
  ['left', 95, -11, 141, 20.5], ['left', 141, -11.7, 156, -1],                          // Thailand, Malaysia, Singapore, Brunei, Indonesia, Timor, Papua New Guinea
  ['right', 60.5, 29.9, 66.2, 37.5], ['right', 66.2, 31.9, 69.3, 37.5], ['right', 78.5, 31.2, 97.5, 37.5], ['right', 88.9, 28.4, 97.5, 31.2], // Afghanistan, Tibet
  ['left', 60.9, 5.8, 97.4, 37.1],                                                      // India, Pakistan, Bangladesh, Nepal, Bhutan, Sri Lanka
  ['right', 28.8, -4.5, 30.9, -1.06], ['right', 22, -12.1, 28.5, -8.2],                 // Rwanda, Burundi, Katanga
  ['left', 11.7, -35, 41, -17.5], ['left', 22, -17.5, 41, -8.2], ['left', 29.6, -11.7, 41, 4.2], // southern and eastern Africa
  ['left', -59.9, 3.5, -54.05, 8.6], ['left', -78.4, 17.7, -76.1, 18.6], ['left', -61.95, 10, -60.5, 11.4], // Guyana, Suriname, Jamaica, Trinidad
];
export function driveSide([lon, lat]) {
  for (const [side, w, s, e, n] of DRIVE_SIDE) if (lon >= w && lon <= e && lat >= s && lat <= n) return side;
  return 'right';
}
