// Saved routes, kept in this browser's IndexedDB (per origin: http://localhost:8787 and :8788 are separate), so a
// 1,600 km tour with its line and per-leg results fits (localStorage holds about 5 MB in all).
//   database 'cyclescape', two stores keyed by the route's id:
//     'routes'     what the Saved routes window lists: { id, name, created, updated, lengthM, gainM, lossM, stops, legs, loop }
//     'routeData'  the route itself: { id, v: 2, parts (route points, stops as p[2] = 1), settings, props,
//                  legs: [{ opt, route (tour.mjs packRoute: the leg's chosen route) }] }
//                  or, moved over from the old starred list, { id, v: 1, parts, settings, optIdx, route, props, … }
// The list is read once (initSaved) and kept in memory, so the app can look names up without waiting. Routes starred
// before (localStorage 'cyclescape.saved.v1') are moved over once, whole, and the old list is left where it is.
// Storage can be missing (private windows): every call is guarded and reports failure to the caller.
const DB = 'cyclescape', META = 'routes', DATA = 'routeData', OLD_KEY = 'cyclescape.saved.v1', MOVED_KEY = 'cyclescape.saved.moved';
const req = (r) => new Promise((resolve, reject) => { r.onsuccess = () => resolve(r.result); r.onerror = () => reject(r.error); });
const done = (tx) => new Promise((resolve, reject) => { tx.oncomplete = () => resolve(true); tx.onerror = tx.onabort = () => reject(tx.error ?? new Error('storage failed')); });
let dbp = null, metas = [];
const open = () => (dbp ??= new Promise((resolve, reject) => {
  const r = indexedDB.open(DB, 1);
  r.onupgradeneeded = () => { for (const s of [META, DATA]) if (!r.result.objectStoreNames.contains(s)) r.result.createObjectStore(s, { keyPath: 'id' }); };
  r.onsuccess = () => resolve(r.result); r.onerror = () => reject(r.error);
}).catch((e) => { dbp = null; throw e; }));
const newId = () => `r${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}`;
// both stores in one transaction: a route is never listed without its data
async function put(meta, data) {
  const tx = (await open()).transaction([META, DATA], 'readwrite');
  tx.objectStore(META).put(meta); if (data) tx.objectStore(DATA).put({ ...data, id: meta.id });
  await done(tx);
  metas = [meta, ...metas.filter((m) => m.id !== meta.id)];
  return meta;
}

// An old starred entry as the two records kept now. Nothing is dropped: the data record is the entry itself.
export function legacyRecords(list) {
  return (Array.isArray(list) ? list : []).filter((e) => e && e.id).map((e) => {
    const pts = (e.parts ?? []).flat();
    return { meta: { id: e.id, name: e.name ?? 'Route', created: e.created ?? null, updated: e.created ?? null, lengthM: e.route?.lengthM ?? null, gainM: e.route?.gainM ?? null,
      lossM: e.route?.lossM ?? null, stops: pts.filter((p, i) => i > 0 && i < pts.length - 1 && p[2] === 1).length, legs: null, loop: false },
    data: { ...e, v: 1 } };
  });
}
// The list in the order the window shows it: by 'name' or 'date' (when it was last saved), dir 1 = A to Z / oldest first
export function sortSaved(list, by = 'date', dir = -1) {
  const key = by === 'name' ? (m) => String(m.name ?? '').toLocaleLowerCase() : (m) => m.updated ?? m.created ?? '';
  return list.slice().sort((a, b) => { const x = key(a), y = key(b); return dir * (by === 'name' ? x.localeCompare(y) : x < y ? -1 : x > y ? 1 : 0) || String(a.id).localeCompare(String(b.id)); });
}

// Open the database, move the old starred list over (once), and read the list. Resolves with the list; on failure
// the list is empty and saving reports the error.
export async function initSaved() {
  try {
    const db = await open();
    let moved = true, old = null;
    try { moved = !!localStorage.getItem(MOVED_KEY); old = JSON.parse(localStorage.getItem(OLD_KEY) ?? 'null'); } catch { /* storage off */ }
    if (!moved && Array.isArray(old) && old.length) {
      const tx = db.transaction([META, DATA], 'readwrite'), have = new Set(await req(tx.objectStore(META).getAllKeys()));
      for (const { meta, data } of legacyRecords(old)) if (!have.has(meta.id)) { tx.objectStore(META).put(meta); tx.objectStore(DATA).put(data); }
      await done(tx);
    }
    if (!moved) { try { localStorage.setItem(MOVED_KEY, new Date().toISOString()); } catch { /* storage off */ } }
    metas = await req(db.transaction(META).objectStore(META).getAll());
  } catch (e) { console.warn('saved routes: storage is not available', e); metas = []; }
  return metas;
}
export const listSaved = () => metas;
export const getSaved = (id) => metas.find((m) => m.id === id) ?? null;
// Save a route: a new one, or over the one with meta.id (which keeps its creation date). Returns its list entry, or
// null when storage is unavailable or full.
export async function saveRoute(meta, data) {
  const now = new Date().toISOString(), old = meta.id ? getSaved(meta.id) : null;
  try { return await put({ ...meta, id: old?.id ?? newId(), created: old?.created ?? now, updated: now }, data); } catch (e) { console.warn('saved routes: storage failed', e); return null; }
}
export async function loadRoute(id) {
  try { return (await req((await open()).transaction(DATA).objectStore(DATA).get(id))) ?? null; } catch (e) { console.warn('saved routes: storage failed', e); return null; }
}
export async function renameSaved(id, name) {
  const m = getSaved(id); if (!m) return null;
  try { return await put({ ...m, name }); } catch (e) { console.warn('saved routes: storage failed', e); return null; }
}
// a copy under another name, saved now
export async function duplicateSaved(id, name) {
  const m = getSaved(id), data = m && await loadRoute(id); if (!data) return null;
  return saveRoute({ ...m, id: null, name }, data);
}
export async function removeSaved(id) {
  try {
    const tx = (await open()).transaction([META, DATA], 'readwrite');
    tx.objectStore(META).delete(id); tx.objectStore(DATA).delete(id);
    await done(tx); metas = metas.filter((m) => m.id !== id); return true;
  } catch (e) { console.warn('saved routes: storage failed', e); return false; }
}
