// Region packs: the road tileset (tileset.mjs, CONTRACT §7) as one file per major region of Japan, which the app
// downloads whole and keeps in this browser, then reads leaf by leaf (format and rules: CONTRACT §7b).
// scripts/pack-tileset.mjs writes them; the app (app.mjs) decides which packs a route needs, asks, downloads them
// here; the build worker (live/build-worker.mjs) reads the roads out of them with readTileset.
//
// Storage: IndexedDB database 'cyclescape-packs', store 'packs', one record per pack:
//   { id, sha256, bytes, name, ja, built, stored, blob }
// The pack is kept as one Blob. Browsers keep a large Blob in IndexedDB as a file of its own and hand back a Blob
// backed by that file, so a leaf is read with blob.slice(offset, end).arrayBuffer(): only those bytes are read, and
// the pack is never in memory as a whole after it was stored.
import { leavesFor } from './tileset.mjs';

export const PACK_FORMAT = 'cyclescape-pack', PACK_VERSION = 1;
const MAGIC = [0x43, 0x53, 0x50, 0x4b], PAGE = 4096; // "CSPK"; the leaves start on a 4 KiB boundary

// File layout: "CSPK" | u8 version | 3 zero bytes | u32 LE H | H bytes of header JSON (padded with spaces) | leaves.
// The header is `fields` plus { leaves: count, bytes: file size, dir: [[z, x, y, offset, length], ...] }, offsets
// from the start of the file. entries: [[z, x, y, length], ...] in file order. Returns the header bytes and the dir.
export function packHeader(fields, entries) {
  for (let start = PAGE; ; start += PAGE) {
    let off = start;
    const list = entries.map(([z, x, y, len]) => { const e = [z, x, y, off, len]; off += len; return e; });
    const json = new TextEncoder().encode(JSON.stringify({ ...fields, leaves: list.length, bytes: off, dir: list }));
    if (12 + json.length > start) continue;
    const head = new Uint8Array(start).fill(0x20);
    head.set(MAGIC, 0); head[4] = PACK_VERSION; head[5] = head[6] = head[7] = 0;
    new DataView(head.buffer).setUint32(8, start - 12, true);
    head.set(json, 12);
    return { head, dir: { list, bytes: off } };
  }
}
// The header of a pack from its first bytes (at least 12 + H): the parsed JSON, or an error for a file that is not one.
export function parsePackHeader(u8) {
  if (MAGIC.some((b, i) => u8[i] !== b)) throw new Error('not a road pack');
  if (u8[4] !== PACK_VERSION) throw new Error(`road pack version ${u8[4]}`);
  const H = new DataView(u8.buffer, u8.byteOffset).getUint32(8, true);
  if (u8.length < 12 + H) return { need: 12 + H };
  const h = JSON.parse(new TextDecoder().decode(u8.subarray(12, 12 + H)));
  if (h.format !== PACK_FORMAT) throw new Error(`unknown pack format ${h.format}`);
  return h;
}
// A Blob (or anything with slice()/arrayBuffer()) holding a pack -> fetchLeaf for readTileset over its leaves
export async function packReader(blob) {
  let h = parsePackHeader(new Uint8Array(await blob.slice(0, PAGE).arrayBuffer()));
  if (h.need) h = parsePackHeader(new Uint8Array(await blob.slice(0, h.need).arrayBuffer()));
  if (blob.size !== h.bytes) throw new Error(`road pack ${h.id}: ${blob.size} bytes, header says ${h.bytes}`);
  const dir = new Map(h.dir.map(([z, x, y, off, len]) => [`${z}/${x}/${y}`, [off, len]]));
  return { header: h, has: (t) => dir.has(`${t.z}/${t.x}/${t.y}`),
    fetchLeaf: async (t) => { const e = dir.get(`${t.z}/${t.x}/${t.y}`); if (!e) throw new Error(`road tile ${t.z}/${t.x}/${t.y} is not in pack ${h.id}`); return new Uint8Array(await blob.slice(e[0], e[0] + e[1]).arrayBuffer()); } };
}

// packs.json (doc): { format: 'cyclescape-packs', version: 1, tileset: index.json without its leaves,
//   packs: [{ id, name, ja, file, bytes, sha256, bbox, outline, leaves }], leaves: [[z, x, y, bytes, pack], ...] }
export const tilesetIndex = (doc) => ({ ...doc.tileset, leaves: doc.leaves });
// The packs a read needs ({ route, bufM } | { area }), as indexes into doc.packs; none: the place is outside them all.
const packOfLeaf = new WeakMap();
export function packsFor(doc, where) {
  let at = packOfLeaf.get(doc);
  if (!at) packOfLeaf.set(doc, (at = new Map(doc.leaves.map((l) => [`${l[0]}/${l[1]}/${l[2]}`, l[4]]))));
  return [...new Set(leavesFor(doc, where).map((t) => at.get(`${t.z}/${t.x}/${t.y}`)))].sort((a, b) => a - b);
}
export const packUrl = (base, p) => new URL(p.file, new URL(base.endsWith('/') ? base : `${base}/`, globalThis.location?.href)).href;
export async function loadPacksDoc(base, fetchFn = fetch) {
  const r = await fetchFn(packUrl(base, { file: 'packs.json' }), { cache: 'no-cache' });
  if (!r.ok) throw new Error(`packs.json: HTTP ${r.status}`);
  const doc = await r.json();
  if (doc.format !== 'cyclescape-packs' || doc.version !== 1) throw new Error(`unknown packs.json format ${doc.format} ${doc.version}`);
  return doc;
}

// ---- this browser's packs (IndexedDB) ----
const DB = 'cyclescape-packs', STORE = 'packs';
let dbp = null;
const db = () => (dbp ??= new Promise((res, rej) => {
  const r = indexedDB.open(DB, 1);
  r.onupgradeneeded = () => r.result.createObjectStore(STORE, { keyPath: 'id' });
  r.onsuccess = () => { r.result.onversionchange = () => { r.result.close(); dbp = null; }; res(r.result); };
  r.onerror = () => { dbp = null; rej(r.error); };
}));
const tx = async (mode, fn) => { const d = await db(); return new Promise((res, rej) => { const t = d.transaction(STORE, mode), q = fn(t.objectStore(STORE)); t.oncomplete = () => res(q?.result); t.onerror = t.onabort = () => rej(t.error ?? new Error('aborted')); }); };
// every stored pack, without its blob: [{ id, sha256, bytes, name, ja, built, stored }]
export async function storedPacks() {
  try { const all = await tx('readonly', (s) => s.getAll()); return all.map(({ blob, ...m }) => m); } catch { return []; }
}
export const packRecord = (id) => tx('readonly', (s) => s.get(id));
export const deletePack = (id) => tx('readwrite', (s) => s.delete(id));
export const clearPacks = () => tx('readwrite', (s) => s.clear());

// Download one pack whole, check its size and SHA-256 against packs.json, and store it. onBytes(n) as it arrives;
// signal: an AbortSignal (Cancel). Nothing is stored unless the whole file arrived and checks out. Without WebCrypto
// (a page on plain http other than localhost) only the size is checked.
export async function downloadPack(base, p, { onBytes = () => {}, signal } = {}) {
  const r = await fetch(packUrl(base, p), { signal, cache: 'no-store' }); // no-store: not a second copy in the HTTP cache
  if (!r.ok) throw Object.assign(new Error(`${p.file}: HTTP ${r.status}`), { unreachable: true });
  const buf = new Uint8Array(p.bytes), rd = r.body.getReader();
  let n = 0;
  for (;;) {
    const { done, value } = await rd.read(); if (done) break;
    if (n + value.length > buf.length) { rd.cancel(); throw new Error(`${p.file}: larger than packs.json says`); }
    buf.set(value, n); n += value.length; onBytes(n);
  }
  if (n !== p.bytes) throw new Error(`${p.file}: ${n} bytes, packs.json says ${p.bytes}`);
  if (globalThis.crypto?.subtle) {
    const h = [...new Uint8Array(await crypto.subtle.digest('SHA-256', buf))].map((b) => b.toString(16).padStart(2, '0')).join('');
    if (h !== p.sha256) throw new Error(`${p.file}: content does not match packs.json`);
  }
  const rec = { id: p.id, sha256: p.sha256, bytes: p.bytes, name: p.name, ja: p.ja, built: p.built ?? null, stored: Date.now() };
  await tx('readwrite', (s) => s.put({ ...rec, blob: new Blob([buf]) }));
  try { await navigator.storage?.persist?.(); } catch { /* best effort: ask the browser not to evict it */ }
  return rec;
}
